import { createTestContext } from '../../../../test-utils'
import { Diagnostic, path } from '@servicenow/sdk-build-core'

describe('EndFlow Diagnostics', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('EndFlow - Block Placement Validation', () => {
        test('should error when EndFlow is directly in flow body', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'endflow-in-body.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        // Invalid: EndFlow at flow body level
        wfa.flowLogic.endFlow({ $id: Now.ID['end'] })
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const error = diagnostics.find(
                (d) => d.message === 'End Flow must be used within a Do Until, For Each, or If block'
            )
            expect(error).toBeDefined()
            expect(error?.level).toBe(Diagnostic.Level.Error)
        })

        test('should NOT error when EndFlow is inside If block', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'endflow-in-if.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        wfa.flowLogic.if({ $id: Now.ID['if'], condition: 'true' }, () => {
            // Valid: EndFlow in If block
            wfa.flowLogic.endFlow({ $id: Now.ID['end'] })
        })
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const endFlowErrors = diagnostics.filter((d) => d.message.includes('End Flow must be used within'))
            expect(endFlowErrors.length).toBe(0)
        })

        test('should NOT error when EndFlow is inside ElseIf block', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'endflow-in-elseif.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        wfa.flowLogic.if({ $id: Now.ID['if'], condition: 'false' }, () => {
            console.log('if branch')
        })
        wfa.flowLogic.elseIf({ $id: Now.ID['elseif'], condition: 'true' }, () => {
            // Valid: EndFlow in ElseIf block
            wfa.flowLogic.endFlow({ $id: Now.ID['end'] })
        })
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const endFlowErrors = diagnostics.filter((d) => d.message.includes('End Flow must be used within'))
            expect(endFlowErrors.length).toBe(0)
        })

        test('should NOT error when EndFlow is inside Else block', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'endflow-in-else.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        wfa.flowLogic.if({ $id: Now.ID['if'], condition: 'false' }, () => {
            console.log('if branch')
        })
        wfa.flowLogic.else(() => {
            // Valid: EndFlow in Else block
            wfa.flowLogic.endFlow({ $id: Now.ID['end'] })
        })
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const endFlowErrors = diagnostics.filter((d) => d.message.includes('End Flow must be used within'))
            expect(endFlowErrors.length).toBe(0)
        })

        test('should NOT error when EndFlow is inside ForEach', async () => {
            const project = ctx.createProject()
            const file = project.addFile({
                path: 'endflow-in-foreach.now.ts',
                content: `
import '@servicenow/sdk/global'
import { Flow, wfa } from '@servicenow/sdk/automation'

Flow(
    {
        $id: Now.ID['test_flow'],
        name: 'Test Flow',
    },
    undefined,
    () => {
        wfa.flowLogic.forEach(
            ['a', 'b'],
            { $id: Now.ID['foreach'] },
            (item) => {
                // Valid: EndFlow in ForEach
                wfa.flowLogic.endFlow({ $id: Now.ID['end'] })
            }
        )
    }
)
                `,
            })

            const diagnostics = await file.getDiagnostics()
            const endFlowErrors = diagnostics.filter((d) => d.message.includes('End Flow must be used within'))
            expect(endFlowErrors.length).toBe(0)
        })
    })
})
